def backfill_besoins(apps, schema_editor):
    """Reprend les affectations historiques (UniteProfesseur) dans le nouveau
    modèle de besoins, puis resynchronise les modules des formateurs."""
    Affectation = apps.get_model('core', 'AffectationEnseignement')
    UniteEnseignement = apps.get_model('core', 'UniteEnseignement')
    Professeur = apps.get_model('core', 'Professeur')

    Affectation.objects.filter(professeur__isnull=False).update(statut='affecte')
    Affectation.objects.filter(professeur__isnull=True).exclude(
        statut__in=['a_pourvoir', 'vacataire_a_recruter']
    ).update(statut='a_pourvoir')

    unites = UniteEnseignement.objects.prefetch_related(
        'unite_groupes', 'unite_professeurs'
    )
    for ue in unites.iterator(chunk_size=200):
        prof_ids = {
            up.professeur_id
            for up in ue.unite_professeurs.all()
            if up.mode == 'presentiel'
        }
        if not prof_ids:
            continue
        for ug in ue.unite_groupes.all():
            for prof_id in prof_ids:
                Affectation.objects.get_or_create(
                    professeur_id=prof_id,
                    module_id=ue.module_id,
                    groupe_id=ug.groupe_id,
                    defaults={'statut': 'affecte'},
                )

    for prof in Professeur.objects.all().iterator():
        module_ids = list(
            Affectation.objects.filter(professeur_id=prof.id)
            .values_list('module_id', flat=True)
            .distinct()
        )
        prof.modules.set(module_ids)


